-- 单表查询
SELECT
    quantile(
        CASE WHEN vp_rowid % 4 = 0 THEN NULL ELSE c0 END,
        0.5
    ) AS median,
    histogram(
        CASE WHEN vp_rowid % 4 = 0 THEN NULL ELSE c0 END
    ) AS hist
FROM repro_duckdb_db5_hist_min_source;

SELECT vp_rowid, c0
FROM repro_duckdb_db1_interval_source
ORDER BY vp_rowid;
